import json
import pathlib

expectations = {
    'row05': {
        'path': pathlib.Path('docs/results/rtx-5070-ti-2026-08-29-c11-integrated-row05-profile.json'),
        'fused': 240,
        'native': 30,
        'backends': {'triton': 120, 'sdpa': 0, 'reference': 0},
    },
    'row11': {
        'path': pathlib.Path('docs/results/rtx-5070-ti-2026-08-29-c11-integrated-row11-profile.json'),
        'fused': 240,
        'native': 30,
        'backends': {'triton': 120, 'sdpa': 0, 'reference': 0},
    },
    'row06': {
        'path': pathlib.Path('docs/results/rtx-5070-ti-2026-08-29-c11-integrated-row06-profile.json'),
        'fused': 80,
        'native': 10,
        'backends': {'triton': 20, 'sdpa': 0, 'reference': 20},
    },
}
output = {}
for name, expected in expectations.items():
    payload = json.loads(expected['path'].read_text())
    events = {event['name']: event for event in payload['top_events']}
    actual = {
        'fused_count': events['_residual_layer_norm_fwd']['count'],
        'native_norm_count': events['aten::native_layer_norm']['count'],
        'backends': payload['backend_counts'],
    }
    output[name] = actual
    assert actual['fused_count'] == expected['fused']
    assert actual['native_norm_count'] == expected['native']
    assert actual['backends'] == expected['backends']
print(json.dumps(output, indent=2))

